export function fixtureForFile(name) {
  const n=String(name||"").toLowerCase();
  if(n.includes("sahyadri_bank_savings")) return {key:"bank", label:"Sahyadri Bank CSV", minCount:50, transactions:DEMO_FIXTURES.filter(t=>t.source.includes("sahyadri_bank"))};
  if(n.includes("nimbus_card")) return {key:"card", label:"Nimbus Card PDF", minCount:40, transactions:DEMO_FIXTURES.filter(t=>t.source.includes("nimbus_card"))};
  if(n.includes("zenith_softworks")) return {key:"payslip", label:"Zenith Softworks payslips", minCount:3, transactions:DEMO_FIXTURES.filter(t=>t.source.includes("zenith_softworks"))};
  if(n.includes("shopzone") && n.endsWith(".eml")) return {key:"email", label:"ShopZone receipt email", minCount:1, transactions:DEMO_FIXTURES.filter(t=>t.source.endsWith("shopzone.eml"))};
  return null;
}
